//! The residual Helmholtz energy of the PC-SAFT model against the exact-source
//! library.
//! Generated by tools/rust_port/validate_pcsaft_state.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::pc_saft::RGAS;

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn the_state_matches_the_source() {
    let mut rows = include_str!("fixtures/pcsaft_state.csv").lines();
    let header = rows.next().expect("the header of the fixture");
    assert_eq!(header, "case;alpha;alpha_rho;alpha_t");
    let mut compared = 0;
    for row in rows {
        let fields: Vec<&str> = row.split(';').collect();
        assert_eq!(fields.len(), 4, "row {row}");
        let case: Vec<&str> = fields[0].split('|').collect();
        assert_eq!(case.len(), 4, "case {row}");
        let components: Vec<&str> = case[0].split(',').collect();
        let temperature: f64 = case[1].parse().expect("the temperature");
        let volume: f64 = case[2].parse().expect("the volume");
        let moles: Vec<f64> = case[3]
            .split(',')
            .map(|value| value.parse().expect("the number of moles"))
            .collect();
        let total: f64 = moles.iter().sum();
        let composition: Vec<f64> = moles.iter().map(|amount| amount / total).collect();
        let rho = total / volume;

        let model = thermopack_rs::PcSaft::new(&components).expect("the model of the case");
        let prepared = model
            .prepare(temperature, &composition)
            .expect("the prepared state of the case");
        let alpha = prepared.residual_helmholtz_energy(rho);
        let compressibility = prepared.compressibility_factor(rho);
        let alpha_rho = (compressibility - 1.0) / rho;
        let state = prepared.state(rho).expect("the state of the case");
        let alpha_t = -state.u_residual / (RGAS * temperature * temperature);

        let native = [alpha, alpha_rho, alpha_t];
        for (position, (source, native)) in fields[1..].iter().zip(native.iter()).enumerate() {
            let source: f64 = source.parse().expect("the source value");
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "entry {position} of the case {row}: source {source} native {native}"
            );
        }
        compared += 1;
    }
    assert!(compared > 0, "the fixture holds no case");
}

#[test]
fn the_temperature_derivative_of_a_mixture_is_not_the_one_of_the_pure_fluid() {
    // The temperature derivative of the residual Helmholtz energy of a
    // mixture follows the chain rule of the hard-sphere model of Boublik and
    // differs from the derivative of the simplified model.
    let pure = thermopack_rs::PcSaft::new(&["CO2"]).expect("the model");
    let mixture = thermopack_rs::PcSaft::new(&["CO2", "C1"]).expect("the model");
    let rho = 100.0;
    let pure_state = pure
        .prepare(300.0, &[1.0])
        .expect("the prepared state")
        .state(rho)
        .expect("the state");
    let mixture_state = mixture
        .prepare(300.0, &[0.5, 0.5])
        .expect("the prepared state")
        .state(rho)
        .expect("the state");
    let pure_t = -pure_state.u_residual / (RGAS * 300.0 * 300.0);
    let mixture_t = -mixture_state.u_residual / (RGAS * 300.0 * 300.0);
    assert!((pure_t - mixture_t).abs() > 1.0e-12);
}
